class Cinematics {
  constructor() {
    this.chain = [];
    this.ready = null;
    this.active = null;
    this.previous = null;
    this.evadedAt = -100;
  }

  clear() {
    this.chain.length = 0;
    this.ready = null;
  }

  register(kind, target, time, armed, airborne) {
    this.chain = this.chain.filter(hit => time - hit.time <= 3.2);
    this.chain.push({kind, time, airborne});
    if (this.chain.length < 3 || target.hp <= 0) return;
    const kinds = this.chain.map(hit => hit.kind);
    const options = [];
    if (armed && kinds.filter(k => k === 'blade').length >= 2) options.push('blade');
    if (!armed && time - this.evadedAt < 3.2) options.push('counter');
    if (!armed && this.chain.some(hit => hit.airborne)) options.push('air');
    if (!armed && kinds.includes('kick') && kinds.includes('fist')) options.push('heel');
    if (!armed && kinds.filter(k => k === 'fist').length >= 2) options.push('rapid');
    const id = options.find(option => option !== this.previous);
    if (id) this.ready = {id, until:time+4};
  }

  start(game) {
    const p = game.player;
    if (!this.ready || this.ready.until < game.time || p.stun > 0 || p.down > 0 ||
        p.dodge > 0 || p.recover > 0 || game.state !== 'fight' || this.active) return false;
    const id = this.ready.id;
    if ((id === 'blade') !== bladed(p)) return false;
    const target = game.enemies.filter(e => e.hp > 0 && Math.abs(e.x-p.x) < 168 &&
      Math.abs(e.y-p.y) < 105).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];
    if (!target) return false;
    this.previous = id;
    this.clear();
    this.active = {id,target,elapsed:0,beat:0,slowLeft:.12,facing:Math.sign(target.x-p.x)||p.face};
    p.attack = null;
    p.buffer = null;
    target.attack = null;
    game.emit('sequence',p.x,p.y,{id});
    return true;
  }

  step(game, dt) {
    const s = this.active;
    if (!s) return;
    const move = MOVES[s.id], p = game.player, e = s.target;
    s.elapsed += dt;
    s.slowLeft = Math.max(0, s.slowLeft - dt);
    p.face = s.facing;
    p.guard = false;
    // The actors still go through the same collision solver as normal combat.
    const incoming = move.beats[s.beat];
    p.turn = 1;
    if (incoming && e.hp > 0) {
      const distance = (e.x-p.x)*s.facing;
      const counterStep = s.id === 'counter' && s.elapsed < .18;
      p.vx = s.facing * (counterStep ? -230 : Math.max(-120, Math.min(470,(distance-52)*12)));
      if (counterStep) {
        p.pose = 'dodge';
        p.poseLeft = .24;
      }
      const windup = incoming[0] - s.elapsed;
      if (incoming[1] === 'spin' && windup > 0 && windup < .17) {
        p.turn = .76 + .24 * Math.cos((1 - windup / .17) * Math.PI * 2);
        p.pose = 'spin';
        p.poseLeft = .09;
      }
      if (s.id === 'air' && s.beat > 0 && s.beat < 3) {
        p.vy = Math.max(-390, Math.min(355,(e.y-p.y)*8 - 55));
      }
      if (s.elapsed >= incoming[0]) {
        const [,pose,damage,force,lift] = incoming;
        p.pose = pose;
        p.poseLeft = .28;
        if (s.id === 'air' && s.beat === 0) { p.vy = -470; p.grounded = false; }
        if (s.id === 'air' && s.beat === 2) p.vy = 300;
        const close = Math.abs(e.x-p.x)<(s.id==='blade'?140:108) && Math.abs(e.y-p.y)<(s.id==='air'?115:88);
        if (close) game.strike(p,e,{damage,force,lift,kind:s.id==='blade'?'blade':pose.includes('Kick')||pose==='spin'||pose==='kick'?'kick':'fist',heavy:s.beat===2,special:true});
        s.slowLeft = .08;
        s.beat++;
      }
    }
    if (s.elapsed >= move.length) {
      p.vx *= .45;
      p.turn = 1;
      this.active = null;
    }
  }

  label(time, armed) {
    return this.ready && (this.ready.id === 'blade') === armed && time <= this.ready.until ? MOVES[this.ready.id].name : '';
  }
}

