function makeRoom(chapter,index,entry){
  const [title,place,groups,layout,detail,after]=entry;
  const [asset,frame,sky,trim,rain,ground]=setting[place];
  const boss=groups.length===1&&Object.hasOwn(bossHealth,groups[0])?groups[0]:null;
  const span=layout==='stairs'?1170:layout==='yard'?1090:layout==='roof'?1130:1020;
  const travel=!groups.length;
  const end=travel?(layout==='climb'?1430:1630):boss?1450:groups.length*span+840;
  const blocks=[], ladders=[];
  const waves=groups.map((group,i)=>{
    const base=330+i*span;
    const roster=boss?[{kind:boss,x:900,hp:bossHealth[boss]}]:Array.from(group,(code,j)=>({
      kind:fighter[code],x:base+390+j*102,
      hp:({r:82,g:103,p:93,c:99,s:108,a:97,h:142,k:154,u:162,m:150,q:174,y:184,t:221,n:160,d:188})[code]+chapter*6
    }));
    if(!boss) {
      let x=base-124;
      for(const [w,h] of layouts[layout]){
        blocks.push({x,y:FLOOR-h,w});
        if(layout==='stairs')ladders.push({x:x-26,y:FLOOR-h,bottom:FLOOR});
        x+=w+13;
      }
    }
    return {trigger:boss?195:base-25,gate:boss?1190:base+span-86,roster};
  });
  const markers=[];
  if(travel){
    const climb=layout==='climb';
    const route=climb?[[315,94,244],[641,176,255]]:[[430,72,196],[848,82,212]];
    for(const [x,rise,w] of route){
      const y=FLOOR-rise;
      blocks.push({x,y,w});
      if(climb)ladders.push({x:x-26,y,bottom:FLOOR});
      markers.push({x:x+Math.round(w*.54),y});
    }
  }
  if(boss==='kazuo')blocks.push({x:485,y:FLOOR-83,w:114},{x:1044,y:FLOOR-70,w:85});
  return {id:'c'+chapter+'r'+(index+1),chapter,title,asset,frame,sky,trim,rain,ground,
    width:end,roof:FLOOR,blocks,ladders,waves,markers,spawn:120,exit:end-95,boss,
    before:Array.isArray(detail)?detail:[],after:after||[],
    travel:travel?layout:null,number:index+1,
    action:typeof detail==='string'?detail:'CONTINUE'};
}
