const CHECKPOINT_KEY='katovia.great.campaign.v1';
function readCheckpoint(storage){
  try {
    const data=JSON.parse(storage.getItem(CHECKPOINT_KEY));
    if(data?.version!==CAMPAIGN_VERSION||!Number.isInteger(data.room)||
      data.room<0||data.room>=ROOMS.length||!Number.isFinite(data.seconds)||data.seconds<0||
      !Number.isInteger(data.best)||data.best<0||typeof data.complete!=='boolean'||
      ((data.complete||data.ending)&&data.room!==ROOMS.length-1)||
      (data.weapon!==undefined&&data.weapon!==null&&!['pipe','blade','bat'].includes(data.weapon))||
      (data.ending!==undefined&&typeof data.ending!=='boolean')||
      (data.after!==undefined&&typeof data.after!=='boolean')||
      (data.after&&(data.ending||data.complete||!ROOMS[data.room].after.length))||
      (data.wave!==undefined&&(!Number.isInteger(data.wave)||data.wave<0||
        data.wave>0&&(data.ending||data.after||data.complete||data.wave>=ROOMS[data.room].waves.length))))return null;
    return data;
  } catch {return null;}
}
function saveCheckpoint(storage,room,seconds,best,complete=false,weapon=null,ending=false,after=false,wave=0){
  const data={version:CAMPAIGN_VERSION,room,seconds,best,complete,weapon,ending,after,wave};
  try {storage.setItem(CHECKPOINT_KEY,JSON.stringify(data));} catch {}
  return data;
}
function chapterStart(chapter){
  return ROOMS.findIndex(room=>room.chapter===chapter);
}




