class Camera {
  constructor(player,world=WORLD) {
    this.world=world;
    const goal = this.target(player);
    this.x=goal.x;
    this.y=goal.y;
    this.shake=0;
    this.shakeTime=0;
    this.phase=0;
  }
  target(p) {
    return {x:clamp(p.x-VIEW.w/2,0,this.world.w-VIEW.w),
      y:clamp(p.y-49-VIEW.h/2,0,this.world.h-VIEW.h)};
  }
  impact(strength) {
    this.shake=Math.max(this.shake,Math.min(strength,6));
    this.shakeTime=.13;
  }
  update(p,dt,sequence) {
    const goal=this.target(p);
    if (sequence) {
      goal.x=clamp(goal.x+sequence.facing*18*Math.sin(Math.min(1,sequence.elapsed/1.5)*Math.PI),0,this.world.w-VIEW.w);
    }
    const weight=1-Math.exp(-dt*(sequence?19:28));
    this.x+=(goal.x-this.x)*weight;
    this.y+=(goal.y-this.y)*weight;
    this.phase+=dt*154;
    this.shakeTime=Math.max(0,this.shakeTime-dt);
  }
  frame() {
    const amplitude=this.shake*this.shakeTime/.13;
    return {x:clamp(this.x+Math.sin(this.phase)*amplitude,0,this.world.w-VIEW.w),
      y:clamp(this.y+Math.cos(this.phase*1.23)*amplitude*.52,0,this.world.h-VIEW.h)};
  }
}

class Game {
  constructor(room=null,startWave=0) {
    this.room=room;
    this.world=room?{w:room.width,h:WORLD.h,roof:room.roof}:WORLD;
    this.blocks=room?.blocks??BLOCKS;
    this.wave=startWave;
    this.waveStarted=false;
    this.marker=0;
    this.gate=null;
    this.cleared=false;
    const spawn=startWave?room.waves[startWave].trigger-146:room?.spawn??820;
    this.player=actor('player',spawn,this.world.roof,100,1);
    this.enemies=room?[]:[actor('rusher',1215,WORLD.roof,103,-1),actor('guard',1485,WORLD.roof,132,-1)];
    this.sword={x:1530,y:this.world.roof,vx:0,vy:0,held:false,kind:'blade'};
    this.weapons=room?(room.id==='c1r3'?[this.sword]:[]):[this.sword];
    this.heldWeapon=null;
    this.camera=new Camera(this.player,this.world);
    this.cinema=new Cinematics();
    this.keys=new Set();
    this.pressed=new Set();
    this.events=[];
    this.time=0;
    this.realTime=0;
    this.acc=0;
    this.hitStop=0;
    this.energy=100;
    this.combo=0;
    this.best=0;
    this.lastHit=-100;
    this.state='fight';
    this.slow=false;
    this.startGrace=1.1;
  }

  emit(type,x,y,data={}) {
    this.events.push({type,x,y,...data});
    if (this.events.length>128) this.events.shift();
  }
  key(code,down) {
    if (down && !this.keys.has(code)) this.pressed.add(code);
    if (down) this.keys.add(code);
    else this.keys.delete(code);
  }
  clearInput() { this.keys.clear(); this.pressed.clear(); }
  held(...keys) { return keys.some(k=>this.keys.has(k)); }
  take(...keys) {
    let used=false;
    for (const k of keys) if (this.pressed.delete(k)) used=true;
    return used;
  }
  attack(actor,name,stage=0) {
    const [start,end,reach,damage,force,lift,kind]=attacks[name];
    actor.attack={name,start,end,reach,damage,force,lift,kind,stage,time:0,hit:new Set(),connected:false,
      heavy:['spin','cleave','kick','airKick','pipeSmash','enemyCleave','heavyCross','tetsuoBlow'].includes(name)};
    this.emit('swing',actor.x,actor.y-50,{kind});
  }
  playerAttack(kick,stage=0) {
    const p=this.player;
    if (p.armed&&!bladed(p)) this.attack(p,kick?'pipeSmash':'pipeSwipe',stage);
    else if (p.armed) this.attack(p,kick?'cleave':stage%2?'reverse':'slash',stage);
    else if (!p.grounded) this.attack(p,kick?'airKick':'airJab',stage);
    else this.attack(p,kick?(stage>=2?'spin':'kick'):stage%2?'cross':'jab',stage);
  }
  input(dt) {
    const p=this.player;
    const axis=Number(this.held('KeyD','ArrowRight'))-Number(this.held('KeyA','ArrowLeft'));
    const jump=this.take('Space','KeyW','ArrowUp');
    const punch=this.take('KeyJ'), kick=this.take('KeyK');
    const dodge=this.take('ShiftLeft','ShiftRight');
    if (this.take('KeyC') && this.cinema.start(this)) return;
    const interact=this.take('KeyE');
    const blocking=this.held('KeyL');
    if (!blocking) p.guardAge=0;
    if (p.stun>0||p.down>0||p.recover>0) { p.guard=false;p.climbing=false;return; }
    if(interact&&this.atExit(90)){
      this.state='won';return;
    }
    const ladder=this.room?.ladders.find(l=>Math.abs(p.x-l.x)<31&&p.y>=l.y-8&&p.y<=l.bottom+4);
    const up=this.held('KeyW','ArrowUp'),down=this.held('KeyS','ArrowDown');
    if(ladder&&!p.attack&&!p.dodge&&(up||down||p.climbing)&&!this.held('Space')&&(!axis||up||down)){
      p.climbing=true;p.guard=false;p.grounded=false;p.vx=p.vy=0;p.x=ladder.x;
      p.y=clamp(p.y+dt*180*(Number(down)-Number(up)),ladder.y,ladder.bottom);
      if(p.y===ladder.y&&up){p.x+=29;p.climbing=false;p.grounded=true;}
      if(p.y===ladder.bottom&&down)p.climbing=false;
      return;
    }
    p.climbing=false;

    if (p.dodge>0) {
      p.vx=p.dodgeDir*610;
      return;
    }
    if (axis && !p.attack && !p.wallLock && p.face!==axis) {
      p.face=axis;
      p.turnTime=.10;
    }
    if (dodge && p.dodgeCooldown<=0) {
      p.dodge=.24; p.dodgeCooldown=.55; p.dodgeDir=axis||p.face;
      p.attack=null; p.buffer=null; p.guard=false; p.vx=p.dodgeDir*610;
      p.pose='dodge'; p.poseLeft=.27;
      this.emit('dash',p.x,p.y);
      return;
    }
    p.guard=blocking&&!p.attack;
    if (p.guard) { if (p.guardAge===0) p.parry=.13; p.guardAge+=dt; }
    if (interact) {
      if (p.armed) {
        const drop=this.heldWeapon||this.sword;
        p.armed=false;p.weaponKind=null;this.heldWeapon=null;
        drop.held=false;drop.x=p.x+p.face*44;drop.y=p.y-36;drop.vx=p.face*125;drop.vy=-135;
        p.attack=null;p.buffer=null;this.emit('drop',p.x,p.y);
      } else {
        const near=this.weapons.filter(w=>!w.held&&Math.abs(w.x-p.x)<78&&Math.abs(w.y-p.y)<65)
          .sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];
        if(near){
          p.armed=true;p.weaponKind=near.kind;near.held=true;this.heldWeapon=near;
          p.attack=null;p.buffer=null;this.emit('equip',p.x,p.y);
        }
      }
    }
    if (jump) {
      if (p.grounded) { p.vy=-550; p.grounded=false; p.airJumps=1; }
      else if (p.wall) {
        p.vy=-550; p.vx=-p.wall*410; p.face=-p.wall; p.wallLock=.19; p.airJumps=1;
      } else if (p.airJumps>0) {
        p.airJumps--; p.vy=-505; this.emit('jump',p.x,p.y);
      }
    }
    if (!p.wallLock) {
      const step=p.attack&&p.grounded&&p.attack.time<p.attack.start+.04;
      const target=axis*(p.guard?110:p.attack?225:345)+(step?p.face*(p.attack.stage?130:85):0);
      const accel=p.grounded?(axis?20:24):axis?6.5:.2;
      p.vx+=(target-p.vx)*(1-Math.exp(-dt*accel));
    }
    if ((punch||kick)&&!p.guard) {
      if (!p.attack) this.playerAttack(kick);
      else p.buffer={kick,left:.39};
    }
    const cancelAt=p.attack?.connected?p.attack.start+.080:(p.attack?.end??0)*.83;
    if (p.attack&&p.buffer&&p.attack.time>=cancelAt) {
      this.playerAttack(p.buffer.kick,Math.min(2,p.attack.stage+1)); p.buffer=null;
    }
  }
  ai(e,dt,index) {
    if(this.room){this.roomAI(e,dt);return;}
    const p=this.player, delta=p.x-e.x, distance=Math.abs(delta);
    if (e.dead||e.stun||e.down||e.recover||e.attack) return;
    e.face=Math.sign(delta)||e.face;
    e.guard=false;
    if (this.startGrace>0) return;
    const incoming=p.attack&&p.face===-e.face&&p.attack.time<p.attack.start;
    if (e.id==='guard' && distance<(p.armed?165:112) && incoming && e.aiWait<=0 && e.aiGuard<=0) {
      e.aiGuard=p.armed?.32:.24; e.aiWait=.62;
      if(p.armed)e.parry=.20;
    }
    if (e.aiGuard>0) { e.guard=true; e.vx*=.91; return; }
    const vertical=Math.abs(p.y-e.y);
    const other=this.enemies.find(o=>o!==e&&o.hp>0);
    const crowded=other && Math.abs(other.x-e.x)<52 && Math.sign(p.x-other.x)===e.face;
    const speed=e.id==='rusher'?214:153;
    if (distance>76 || vertical>73) {
      const target=crowded&&distance<170?-e.face*75:e.face*speed;
      e.vx+=(target-e.vx)*(1-Math.exp(-dt*12));
      if (e.wall===e.face&&e.grounded) { e.vy=-500; e.grounded=false; }
    } else {
      e.vx*=.90;
      if (e.aiWait<=0&&vertical<58) {
        this.attack(e,index===0?'rush':'guardKick');
        e.aiWait=index===0?.63:.93;
      }
    }
  }
  roomAI(e,dt){
    const p=this.player,dx=p.x-e.x,distance=Math.abs(dx),height=Math.abs(p.y-e.y);
    if(e.dead||e.stun||e.down||e.recover||e.attack||this.startGrace>0)return;
    const rule=BEHAVIOR[e.id],phase=e.phase||1;
    e.face=Math.sign(dx)||e.face;
    e.guard=false;
    if(e.counter){
      e.counter=false;e.aiGuard=0;
      if(distance<124&&height<70){this.attack(e,rule.counter);e.aiWait=.8;return;}
    }
    const incoming=p.attack&&p.face===-e.face&&p.attack.time<p.attack.start;
    const block=rule.block==='timed'||(rule.block==='sword'&&(p.armed||e.aiTurn%2===1));
    if(block&&incoming&&distance<158&&e.aiWait<=0){
      e.aiGuard=.25;e.aiWait=e.boss?.57:.71;e.parry=p.armed||rule.block==='timed'?.175:0;
      e.aiTurn++;
    }
    if(e.aiGuard>0){e.guard=true;e.vx*=.88;return;}
    if(rule.evasive&&incoming&&distance<112&&e.dodgeCooldown<=0&&e.aiTurn%2===1){
      e.dodge=.16;e.dodgeCooldown=1.8;e.vx=-e.face*270;e.aiTurn++;return;
    }
    if(e.dodge>0)return;
    if(rule.spacing&&distance<rule.spacing&&height<55&&e.aiWait>0&&e.x>38&&e.x<(this.gate??this.world.w)-38){
      e.vx=-e.face*143;return;
    }
    const reach=phase===2&&rule.second?112:rule.reach;
    const neighbor=this.enemies.find(other=>{
      const front=(other.x-e.x)*e.face;
      return other!==e&&!other.dead&&front<46&&(front>0||front===0&&other.slot<e.slot)&&Math.abs(other.y-e.y)<40;
    });
    if(distance>reach||height>70){
      const pace=rule.speed*(phase===2?1.16:1);
      const desired=neighbor&&distance<190?-e.face*73:e.face*(rule.burst&&distance>120?pace*1.14:pace);
      e.vx+=(desired-e.vx)*(1-Math.exp(-dt*12));
      if(e.grounded&&(e.wall===e.face||(p.y<e.y-75&&distance<105))){
        const wall=this.blocks.find(b=>{
          const edge=e.face>0?b.x:b.x+b.w;
          return Math.abs(edge-e.x)<30&&b.y<e.y-8;
        });
        const rise=Math.max(75,e.y-Math.min(wall?.y??e.y,p.y));
        e.vy=-Math.sqrt(2800*(rise+35));e.grounded=false;
      }
    }else{
      e.vx*=.83;
      if(e.aiWait<=0&&height<65&&!neighbor){
        const moves=phase===2&&rule.second?rule.second:rule.moves;
        const move=rule.closeMove&&distance<74?rule.closeMove:moves[e.aiTurn++%moves.length];
        this.attack(e,move);
        if(move===rule.leap&&e.grounded){e.vy=-420;e.grounded=false;e.vx=e.face*242;}
        e.aiWait=rule.wait*(phase===2?.74:1);
      }
    }
  }
  spawnWave(){
    const wave=this.room.waves[this.wave];
    this.enemies=wave.roster.map(({kind,x,hp},slot)=>{
      const enemy=actor(kind,x,this.world.roof,hp,-1);
      const info=BEHAVIOR[kind];
      enemy.boss=this.room.boss===kind;
      enemy.phase=1;enemy.slot=slot;enemy.aiTurn=0;enemy.aiWait=.32+((x%151)/530);
      enemy.weaponKind=info.weapon||null;enemy.armed=Boolean(info.weapon);
      return enemy;
    });
    this.waveStarted=true;
    this.gate=wave.gate;
    this.startGrace=.36;
    this.emit('wave',this.player.x,this.player.y,{number:this.wave+1,total:this.room.waves.length});
  }
  atExit(radius=42){
    return Boolean(this.room&&this.cleared&&Math.abs(this.player.x-this.room.exit)<radius&&
      Math.abs(this.player.y-this.world.roof)<108);
  }
  progressRoom(dt){
    if(this.cleared){
      if(this.room.action==='CONTINUE'&&this.atExit())this.state='won';
      return;
    }
    if(this.room.travel){
      const target=this.room.markers[this.marker],p=this.player;
      if(Math.abs(p.x-target.x)<38&&Math.abs(p.y-target.y)<25){
        this.marker++;
        this.cleared=this.marker===this.room.markers.length;
        this.emit(this.cleared?'exit':'marker',p.x,p.y);
      }
      return;
    }
    if(!this.waveStarted&&this.player.x>=this.room.waves[this.wave].trigger)this.spawnWave();
    if(!this.waveStarted||this.cinema.active||this.enemies.some(e=>e.hp>0))return;
    this.winDelay=(this.winDelay??.65)-dt;
    if(this.winDelay>0)return;
    this.wave++;
    this.gate=null;this.waveStarted=false;this.winDelay=null;
    this.cleared=this.wave===this.room.waves.length;
    if(!this.cleared){
      this.player.hp=Math.min(100,this.player.hp+24);
      this.energy=Math.min(100,this.energy+20);
    }
    this.emit(this.cleared?'exit':'wave-clear',this.player.x,this.player.y);
  }
  releaseWeapon(enemy){
    if(!enemy.weaponKind)return;
    this.weapons.push({kind:enemy.weaponKind,x:enemy.x,y:enemy.y-42,vx:-enemy.face*110,vy:-160,held:false});
    enemy.weaponKind=null;enemy.armed=false;
  }
  strike(attacker,victim,a) {
    if (victim.hp<=0) return false;
    if (victim.dodge>0) {
      if (victim===this.player) this.cinema.evadedAt=this.time;
      this.emit('evade',victim.x,victim.y-45);
      return false;
    }
    const direction=Math.sign(victim.x-attacker.x)||attacker.face;
    const guarded=victim.guard&&victim.face===-direction&&!a.special;
    if (guarded&&victim.parry>0) {
      attacker.stun=.38; attacker.attack=null; attacker.vx=-direction*230;
      if(this.room&&BEHAVIOR[victim.id]?.counter)victim.counter=true;
      if (victim===this.player) { this.cinema.evadedAt=this.time; this.energy=Math.min(100,this.energy+16); }
      this.hitStop=.06; this.emit('parry',victim.x,victim.y-55);
      return false;
    }
    const damage=guarded?(victim===this.player?Math.ceil(a.damage*.16):0):a.damage;
    victim.hp=Math.max(0,victim.hp-damage);
    victim.flash=.115;
    victim.stun=guarded?.13:a.special?.32:victim.boss?.15:.23;
    victim.attack=null; victim.buffer=null;
    const resistance=this.room&&victim.hp>0?BEHAVIOR[victim.id]?.resist??1:1;
    victim.vx=direction*a.force*resistance*(guarded?.25:victim.boss&&victim.hp>0?.53:1);
    if (!guarded) {
      victim.vy=a.lift*(victim.boss&&victim.hp>0?.53:1); victim.grounded=false;
      if (a.heavy||victim.hp===0) victim.down=victim.boss&&victim.hp>0?.22:.52;
    }
    if (victim.boss&&victim.hp>0&&victim.phase===1&&victim.hp<=victim.maxHp*.50) {
      victim.phase=2;victim.aiTurn=0;victim.aiWait=.62;
      if(victim.id==='kazuo')this.releaseWeapon(victim);
      this.emit('phase',victim.x,victim.y,{id:victim.id});
    }
    if (victim.hp===0) {
      victim.dead=true;victim.down=1;
      if(this.room&&victim!==this.player)this.releaseWeapon(victim);
    }
    if (victim===this.player&&!guarded) { this.combo=0; this.cinema.clear(); }
    if (attacker===this.player&&!guarded) {
      if (!a.special) {
        this.combo=this.time-this.lastHit<3.2?this.combo+1:1;
        this.best=Math.max(this.combo,this.best);
        this.cinema.register(a.kind,victim,this.time,bladed(attacker),!attacker.grounded);
      }
      this.lastHit=this.time;
      this.energy=Math.min(100,this.energy+5);
    }
    this.camera.impact(guarded?1.5:a.heavy?5.7:3.2);
    this.hitStop=Math.max(this.hitStop,guarded?.028:a.heavy?.065:.045);
    this.emit(guarded?'block':'hit',victim.x-direction*11,victim.y-56,
      {direction,heavy:a.heavy,kind:a.kind,special:a.special||false});
    return !guarded;
  }
  resolveAttack(a,targets,dt) {
    const action=a.attack;
    if (!action) return;
    action.time+=dt;
    if (action.time>=action.end) {
      a.attack=null;
      if(this.room&&a.id==='mika'){
        if(action.name==='mikaSnap'&&Math.abs(this.player.x-a.x)<148&&Math.abs(this.player.y-a.y)<70){
          a.face=Math.sign(this.player.x-a.x)||a.face;
          this.attack(a,BEHAVIOR.mika.followup);
        }else a.aiWait=Math.max(a.aiWait,.47);
      }
      return;
    }
    if (action.time<action.start||action.time>action.start+.10) return;
    if (a!==this.player && action.time<action.start+.065) a.vx=a.face*240;
    for (const e of targets) {
      const dx=(e.x-a.x)*a.face;
      if (e.hp>0 && dx>=-19 && dx<=action.reach+18 && Math.abs(a.y-e.y)<(a.grounded?62:78)&&!action.hit.has(e)) {
        action.hit.add(e); action.connected=this.strike(a,e,action)||action.connected;
      }
    }
  }
  motion(a,dt) {
    if(a.climbing)return;
    const ox=a.x, oy=a.y;
    a.wall=0;
    if (!a.grounded) a.vy=Math.min(900,a.vy+1400*dt);
    if (a.down>0||a.dead||a.stun>0) a.vx*=Math.exp(-dt*(a.grounded?4.5:1.15));
    let nx=ox+a.vx*dt, ny=oy+a.vy*dt;
    const radius=19;
    let boundary=0;
    if (nx<radius) {nx=radius;boundary=-1;}
    if (nx>this.world.w-radius) {nx=this.world.w-radius;boundary=1;}
    for (const b of this.blocks) {
      if (oy <= b.y+5||oy>this.world.roof+2) continue;
      if (ox+radius<=b.x+.1&&nx+radius>b.x) {nx=b.x-radius;boundary=1;}
      else if (ox-radius>=b.x+b.w-.1&&nx-radius<b.x+b.w) {nx=b.x+b.w+radius;boundary=-1;}
    }
    if(this.gate!==null&&nx+radius>this.gate){
      nx=this.gate-radius;boundary=1;
    }
    if (boundary) {
      a.wall=boundary;
      if (Math.abs(a.vx)>290&&(a.stun>0||a.down>0||a.dead)) {
        this.emit('wall',nx,ny-46,{direction:-boundary,heavy:true});
        if (a.hp>0) {a.down=Math.max(a.down,.48); a.stun=Math.max(a.stun,.17);}
        a.vx=-boundary*Math.abs(a.vx)*.32;
        this.camera.impact(4);
      } else a.vx=0;
      if (a===this.player&&a.vy>142&&a.stun===0&&a.down===0) { a.vy=142;ny=oy+a.vy*dt; }
    }
    let floor=this.world.roof;
    for (const b of this.blocks) if (nx>b.x-4&&nx<b.x+b.w+4&&oy<=b.y+3&&ny>=b.y-1) floor=Math.min(floor,b.y);
    const landed=ny>=floor && a.vy>=0;
    if (landed) {
      if (!a.grounded&&a.vy>260) {
        a.land=.13;
        if(a.vy>370)this.emit('land',nx,floor);
      }
      a.y=floor;a.vy=0;a.grounded=true;a.airJumps=1;
    } else {a.y=ny;a.grounded=false;}
    a.x=nx;
    a.walk+=Math.abs(a.vx)*dt*.042;
  }
  physics(dt) {
    const p=this.player;
    const seq=this.cinema.active;
    if (seq) {
      this.pressed.clear();
      this.cinema.step(this,dt);
      if (seq.slowLeft>0) dt*=.64;
    }
    else this.input(dt);
    if(this.state!=='fight')return;
    for (const [i,e] of this.enemies.entries()) {
      if (!seq||e!==seq.target) this.ai(e,dt,i);
    }
    if (!seq&&!this.cinema.active) this.resolveAttack(p,this.enemies,dt);
    if (!seq&&!this.cinema.active) for (const e of this.enemies) if (e.hp>0) this.resolveAttack(e,[p],dt);
    for (const a of [p,...this.enemies]) {
      for (const key of ['stun','dodge','dodgeCooldown','parry','flash','poseLeft','aiWait','aiGuard','wallLock','recover','land','turnTime']) a[key]=Math.max(0,a[key]-dt);
      if (a.buffer&&(a.buffer.left-=dt)<=0) a.buffer=null;
      if (a.down>0&&!a.dead&&a.grounded) {
        a.down=Math.max(0,a.down-dt);
        if (!a.down) a.recover=.21;
      }
      this.motion(a,dt);
    }
    for(const s of this.weapons){
      if(s.held)continue;
      const oldY=s.y;
      s.vy+=1400*dt; s.y+=s.vy*dt;
      s.x=clamp(s.x+s.vx*dt,12,this.world.w-12);
      let floor=this.world.roof;
      for (const b of this.blocks) if (s.x>=b.x&&s.x<=b.x+b.w&&oldY<=b.y+.2&&s.y>=b.y) floor=Math.min(floor,b.y);
      if (s.y>=floor) { s.y=floor;s.vy=0;s.vx*=.80; }
    }
    this.startGrace=Math.max(0,this.startGrace-dt);
    if (p.hp<=0) this.state='lost';
    else if(this.room)this.progressRoom(dt);
    else if (!this.cinema.active&&this.enemies.every(e=>e.hp<=0)) {
      this.winDelay=(this.winDelay??.85)-dt;
      if (this.winDelay<=0) this.state='won';
    }
  }
  advance(seconds) {
    if (!Number.isFinite(seconds)||seconds<=0||this.state!=='fight') return;
    this.acc+=Math.min(seconds,.075);
    while (this.acc>=STEP && this.state==='fight') {
      this.acc-=STEP;
      this.realTime+=STEP;
      this.camera.update(this.player,STEP,this.cinema.active);
      if (this.hitStop>0) {this.hitStop-=STEP;continue;}
      this.slow=this.held('KeyQ')&&this.energy>0&&!this.cinema.active;
      this.energy=clamp(this.energy+STEP*(this.slow?-32:3),0,100);
      const dt=STEP*(this.slow?.42:1);
      this.time+=dt;
      if (!this.cinema.active&&this.time-this.lastHit>3.2) this.combo=0;
      this.physics(dt);
    }
  }
}

// Alpha bounds for the whole-body pose sheets.
